before:
Complete local C++ example; the app itself does not execute it:
```cpp
#include <iostream>
#include <string>
std::string describe(int) { return "number"; }
std::string describe(const std::string&) { return "text"; }
int add_bonus(int score, int bonus = 1) { return score + bonus; }

int main()
{
    std::cout << describe(4) << "\n";
    std::cout << add_bonus(4) << "\n";
}

```

